def _business_projection(
    events: Any, expected: Mapping[str, Mapping[str, Any]]
) -> list[dict[str, Any]]:
    projection: list[dict[str, Any]] = []
    seen: set[str] = set()
    for event in events if isinstance(events, list) else []:
        if not isinstance(event, Mapping):
            continue
        event_type = str(event.get("type") or "")
        if not _is_business_event(event_type):
            continue
        payload = _event_payload(event)
        label = next((name for name, wanted in expected.items() if payload == wanted), None)
        if label is None:
            label = f"unexpected:{event_type}:{event.get('seq')}"
        elif label in _REPEATABLE_LABELS and label in seen:
            continue
        seen.add(label)
        projection.append({"label": label, "seq": event.get("seq"), "payload": payload})
    return projection


def _note_predicate(raw: Mapping[str, Any], name: str) -> tuple[bool, Any, Any, str | None]:
    groups = raw.get("groups") if isinstance(raw.get("groups"), Mapping) else {}
    actual = groups.get(name) if isinstance(groups.get(name), Mapping) else {}
    actual_note = actual.get("note") if isinstance(actual.get("note"), Mapping) else {}
    expected = {
        "match_count": 1,
        "note": _NOTE_EXPECTED[name],
        "application_build": EXPECTED_BUILD,
    }
    projected = {
        "match_count": actual.get("match_count"),
        "note": {key: actual_note.get(key) for key in _NOTE_EXPECTED[name]},
        "application_build": actual.get("application_build"),
    }
    passed = projected == expected and isinstance(actual_note.get("id"), str) and bool(actual_note.get("id"))
    return passed, expected, actual, _failure(projected, expected)


